// Dynamic loads from INSIDE a package: NFT's unresolved-require fallback
// globs this package's own directory only, so the sibling packages below are
// invisible to the trace — exactly the garden's createRequire/dynamic-import
// omission classes.
const load = (name) => require(name.split('|').join(''));
module.exports.loadHidden = () => load('hidden|-cjs').ping();
module.exports.loadAsset = () => load('asset|-carrier').read();
module.exports.loadEsm = () => import('hidden|-esm'.split('|').join('')).then((m) => m.ping());
